:host {
    padding-bottom: 1.5rem;
    display: block;
    --rr-blue: #0176d3;
    --rr-blue-2: #eef4ff;
    --rr-link: #0b5cab;
    --rr-ink: #181818;
    --rr-muted: #5c5c5c;
    --rr-line: #e5e5e5;
    --rr-head-bg: #fafaf9;
    --rr-ok: #2e844a;
    --rr-ok-2: #ebf7e6;
    --rr-bad: #ba0517;
    --rr-bad-2: #feded8;
    --rr-warn: #8c4b02;
    --rr-warn-2: #fef1cd;
    --rr-violet: #5a1ba9;
    --rr-violet-2: #f2eafe;
    --rr-mono: ui-monospace, Menlo, Consolas, monospace;
}

/* the page fills the tab's height: the list scrolls inside its card, the page itself doesn't */
.rr-page { display: flex; flex-direction: column; gap: 12px; height: calc(100vh - 190px); min-height: 520px; color: var(--rr-ink); position: relative; }
.rr-page p { margin: 0; }
.rr-card { background: #fff; border: 1px solid var(--rr-line); border-radius: 4px; box-shadow: 0 2px 2px rgba(0, 0, 0, 0.05); min-width: 0; }
.rr-grow { flex: 1 1 auto; }
.rr-weak { color: var(--rr-muted); }
.rr-small { font-size: 12px; }
.rr-strong { font-weight: 600; }
.rr-block { display: block; }
.rr-mono { font-family: var(--rr-mono); font-size: 12px; white-space: nowrap; }
.rr-trunc { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
.rr-pad { padding: 6px 12px; }
.rr-inset { margin: 10px 12px; }
.rr-bad-text { color: #8e030f; }
.rr-hit { background: #fff3b0; border-radius: 2px; }
.rr-msg { padding: 8px 10px; border-radius: 4px; font-size: 12px; flex: none; }
.rr-msg-bad { background: #fef1ee; color: #8e030f; }
.rr-a { color: var(--rr-link); text-decoration: none; white-space: nowrap; }
.rr-a:hover, .rr-link:hover { text-decoration: underline; }
.rr-link { border: 0; background: none; padding: 0; font: inherit; color: var(--rr-link); cursor: pointer; text-align: left; }

.rr-head { flex: none; display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; padding: 10px 14px; position: relative; }
.rr-head-icon { width: 32px; height: 32px; border-radius: 4px; background: #0b827c; flex: none; display: inline-flex; align-items: center; justify-content: center; }
.rr-head-text { flex: 1 1 160px; min-width: 0; }
.rr-kicker { font-size: 12px; color: var(--rr-muted); }
.rr-title { margin: 0; font-size: 17px; font-weight: 700; line-height: 1.2; }

.rr-segs { display: inline-flex; border: 1px solid #c9c9c9; border-radius: 4px; overflow: hidden; flex-wrap: wrap; }
.rr-seg { border: 0; border-right: 1px solid #c9c9c9; background: #fff; padding: 5px 12px; font: inherit; font-size: 12px; cursor: pointer; color: var(--rr-ink); }
.rr-seg:last-child { border-right: 0; }
.rr-seg-on { background: var(--rr-blue); color: #fff; }

.rr-pill { display: inline-block; font-size: 11px; font-weight: 700; padding: 2px 9px; border-radius: 10px; white-space: nowrap; }
.rr-pill-ok { background: var(--rr-ok-2); color: var(--rr-ok); }
.rr-pill-bad { background: var(--rr-bad-2); color: var(--rr-bad); }
.rr-pill-warn { background: var(--rr-warn-2); color: var(--rr-warn); }
.rr-pill-run { background: var(--rr-blue-2); color: var(--rr-blue); }
.rr-pill-none { background: #f3f3f3; color: var(--rr-muted); }
.rr-pill-violet { background: var(--rr-violet-2); color: var(--rr-violet); }

/* org cards */
.rr-orgs { flex: none; display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 10px; }
.rr-org { background: #fff; border: 1px solid var(--rr-line); border-radius: 8px; padding: 10px 12px; display: flex; flex-direction: column; gap: 6px; }
.rr-org-on { border-color: var(--rr-blue); box-shadow: 0 0 0 2px #cfe3fb; }
.rr-org-pick { border: 0; background: none; padding: 0; text-align: left; font: inherit; color: inherit; cursor: pointer; display: flex; flex-direction: column; gap: 3px; }
.rr-org-top { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.rr-big { font-size: 22px; font-weight: 700; line-height: 1.2; color: var(--rr-muted); }
.rr-big-ok { color: var(--rr-ok); }
.rr-big-warn { color: var(--rr-warn); }
.rr-big-run { color: var(--rr-blue); }
.rr-org-actions { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }

/* the list card fills the rest of the page */
.rr-split-card { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; overflow: hidden; }
.rr-split { flex: 1 1 auto; min-height: 0; display: grid; grid-template-columns: 220px 1fr; }
.rr-types { border-right: 1px solid var(--rr-line); overflow-y: auto; }
.rr-ty { display: flex; justify-content: space-between; gap: 8px; width: 100%; border: 0; border-bottom: 1px solid #f1f1f1; background: #fff; padding: 7px 12px; font: inherit; font-size: 12.5px; cursor: pointer; text-align: left; }
.rr-ty-on { background: #f4f8fe; box-shadow: inset 3px 0 0 var(--rr-blue); font-weight: 600; }
.rr-list { min-width: 0; min-height: 0; display: flex; flex-direction: column; flex: 1 1 auto; }
.rr-bar { flex: none; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; padding: 8px 12px; border-bottom: 1px solid var(--rr-line); }
.rr-search { flex: 1 1 220px; min-width: 180px; }
.rr-rows { flex: 1 1 auto; min-height: 120px; overflow-y: auto; }
.rr-row { display: grid; grid-template-columns: 70px minmax(0, 1fr) 160px 170px; gap: 8px; align-items: center; padding: 6px 12px; border-bottom: 1px solid #f1f1f1; font-size: 12.5px; }
.rr-row-route { grid-template-columns: 70px minmax(0, 1fr) 170px 190px; }
.rr-row-head { position: sticky; top: 0; z-index: 1; background: var(--rr-head-bg); font-size: 11px; text-transform: uppercase; letter-spacing: 0.03em; color: var(--rr-muted); }
.rr-row-open { background: #f4f8fe; }
.rr-name { display: flex; flex-direction: column; min-width: 0; color: var(--rr-ink); }
.rr-chip { display: inline-flex; align-items: center; justify-content: center; border: 1px solid #c9c9c9; border-radius: 14px; padding: 2px 10px; font: inherit; font-size: 12px; color: var(--rr-blue); font-weight: 600; background: #fff; cursor: pointer; min-width: 44px; }
.rr-chip-on { background: var(--rr-blue); border-color: var(--rr-blue); color: #fff; }
.rr-empty { padding: 18px 14px; color: var(--rr-muted); font-size: 13px; display: flex; align-items: center; gap: 8px; }
.rr-inline-spin { position: relative; display: inline-block; width: 24px; height: 24px; }

/* an opened component */
.rr-open { flex: none; max-height: 55%; overflow: auto; border-top: 2px solid var(--rr-line); padding-bottom: 8px; }
.rr-open-head { display: flex; align-items: center; gap: 8px; padding: 8px 12px; }
.rr-fpick { display: flex; flex-wrap: wrap; gap: 6px; padding: 0 12px 8px; }
.rr-fp { border: 1px solid #c9c9c9; border-radius: 4px; background: #fff; padding: 3px 9px; font: inherit; font-size: 12px; cursor: pointer; }
.rr-fp-on { border-color: var(--rr-blue); color: var(--rr-blue); font-weight: 600; }
.rr-patch { margin: 0 12px; max-height: 50vh; overflow: auto; font-family: var(--rr-mono); font-size: 11.5px; line-height: 1.45; border: 1px solid var(--rr-line); border-radius: 4px; }
.rr-pl { display: block; padding: 0 10px; white-space: pre; }
.rr-pl-add { background: #e3f5df; }
.rr-pl-del { background: #fde7e4; }
.rr-pl-hunk { background: #eef4ff; color: #014486; }

.rr-foot { flex: none; display: flex; align-items: center; gap: 10px; flex-wrap: wrap; padding: 10px 14px; border-top: 1px solid var(--rr-line); background: var(--rr-head-bg); }

/* down the route */
.rr-lane { flex: none; display: flex; flex-wrap: wrap; gap: 10px; padding: 12px; border-bottom: 1px solid var(--rr-line); }
.rr-pair { display: flex; align-items: center; gap: 10px; border: 1px solid var(--rr-line); border-radius: 8px; background: #fff; padding: 8px 10px; font: inherit; cursor: pointer; }
.rr-pair[aria-pressed='true'] { border-color: var(--rr-blue); box-shadow: 0 0 0 2px #cfe3fb; }
.rr-stage { display: flex; flex-direction: column; text-align: left; min-width: 70px; }
.rr-count { border: 1px solid #d8d8d8; border-radius: 14px; padding: 3px 12px; font-size: 12px; font-weight: 700; color: var(--rr-muted); white-space: nowrap; }
.rr-count-ok { border-color: #9fd6ad; color: var(--rr-ok); }
.rr-count-warn { border-color: #f0c66e; color: #7a4b00; background: var(--rr-warn-2); }

/* installed packages */
.rr-pkg { display: grid; grid-template-columns: minmax(160px, 1.3fr) minmax(0, 2fr) 170px minmax(200px, auto); gap: 8px; align-items: center; padding: 7px 12px; border-bottom: 1px solid #f1f1f1; font-size: 12.5px; }
.rr-pkg-versions { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(60px, 1fr); gap: 6px; }
.rr-pkg-actions { display: flex; gap: 6px; justify-content: flex-end; flex-wrap: wrap; }
.rr-uninstall { flex: none; margin: 10px 12px 12px; border: 1px solid var(--rr-line); border-radius: 8px; background: #fffdf6; padding: 6px 0 0; max-height: 50%; overflow: auto; }
.rr-uninstall > p { padding: 0 12px 6px; }
.rr-use { display: grid; grid-template-columns: 70px minmax(0, 1fr) auto; gap: 8px; align-items: center; padding: 5px 12px; font-size: 12.5px; }

/* countdowns: an invisible element whose animation ends after N seconds (no timers) */
.rr-ticks { position: absolute; left: 0; bottom: 0; width: 1px; height: 1px; overflow: hidden; }
.rr-tick { position: absolute; width: 1px; height: 1px; opacity: 0.01; pointer-events: none; animation: rr-tick 1s linear; }
.rr-tick-2 { animation-duration: 2s; }
.rr-tick-5 { animation-duration: 5s; }
@keyframes rr-tick { from { transform: translateX(0); } to { transform: translateX(1px); } }

@media (max-width: 900px) {
    .rr-split { grid-template-columns: 1fr; }
    .rr-types { display: none; }
    .rr-row, .rr-row-route { grid-template-columns: 60px minmax(0, 1fr) 120px; }
    .rr-row > :last-child { display: none; }
    .rr-pkg { grid-template-columns: 1fr; }
}

/* the Data view (build 43) fills the rest of the page */
.rr-data-view { display: block; flex: 1 1 auto; min-height: 0; }
